#!/usr/bin/env python3
# make_map_header.py - writes src/musicmap.h from the final MusicSFx.mpf (data/MusicSFx.mpf, 7,504 B = the bytes the mod expects to find in
# memory at [map slot+0x34]). It checks the layout constants against UG2's map loader (+0x38 = base+0x20; +0x3C = +0x38 + nodes*2;
# +0x40 = (last node + 0x13 + nbr*4) & ~3, from a decompile, not checked in the exe; UG2-EXE: +0x4C = base + [0x1954]*4, +0x50 = +0x4C + 4 +
# byte[0xD]*4, +0x54 = base + [0x195C]*4), the 27 song waves of UG2's original archive, and the earlier maps the final one extends:
# the UG2 + MW + UG1 map (7,264 B), the UG2 + MW map (7,048 B) and UG2's original map (6,840 B) - each equal to the final map up to 0x195C
# and in its own sample entries.
# usage: make_map_header.py <data/MusicSFx.mpf> <data/MusicSFx_ug2_mw_ug1.mpf> <data/MusicSFx_ug2_mw.mpf> <data/MusicSFx_ug2_original.mpf> <out .h>
import struct, sys, hashlib
mpf, p3, p2, origp, out = sys.argv[1:6]
d = open(mpf, 'rb').read(); assert len(d) == 7504 and d[:4] == b'xDFP' and d[4] == 4, (len(d), d[:5])
assert hashlib.sha256(d).hexdigest() == '34cba3025417d8057959990ed3019a6ffb1a3e2bb4ebea11ef045bb30e7ff409', 'not the final map (34cba302..)'
nn = struct.unpack_from('<H', d, 0x12)[0]; nev = d[0xF]; assert nn == 162 and nev == 79
tab = [struct.unpack_from('<H', d, 0x20 + 2 * i)[0] * 4 for i in range(nn)]
nodetab_end = 0x20 + nn * 2
last = tab[-1]; nbr_last = (struct.unpack_from('<I', d, last + 4)[0] >> 12) & 0x1F
ev_off = (last + 0x13 + nbr_last * 4) & ~3
ev_end = (ev_off + 3 + nev * 2) & ~3
w54, w58, w5c = struct.unpack_from('<III', d, 0x1954)
p4c = w54 * 4; smp = p4c + 4 + d[0xD] * 4; end = struct.unpack_from('<I', d, p4c + d[0xD] * 4)[0] * 4
assert (nodetab_end, ev_off, ev_end, p4c, smp, end) == (0x164, 0xD34, 0xDD4, 0x1958, 0x1960, len(d)), (hex(nodetab_end), hex(ev_off), hex(ev_end), hex(p4c), hex(smp), hex(end))
assert (w54, w58, w5c) == (0x656, 0x658, 0x754)
nent = (end - smp) // 8; assert nent == 126
# the 27 songs' audio nodes: song s enters at node 3s, whose one branch (target at +18) is the audio node; its word 0 low 16 bits = the wave
UG2_SONG_WAVES = [39, 4, 35, 8, 40, 23, 2, 19, 20, 38, 33, 34, 30, 9, 5, 6, 3, 31, 37, 36, 7, 10, 11, 18, 22, 21, 32]
aud = []
for s in range(27):
    e = tab[3 * s]; w1 = struct.unpack_from('<I', d, e + 4)[0]; assert (w1 >> 12) & 0x1F == 1
    a = struct.unpack_from('<H', d, e + 18)[0]; ao = tab[a]; w0 = struct.unpack_from('<I', d, ao)[0]
    assert w0 & 0xFFFF == UG2_SONG_WAVES[s] and (w0 >> 16) == 0x20, (s, hex(w0)); aud.append((s, a, ao, w0))
assert aud[25][1:3] == (77, 0x700) and aud[26][1:3] == (80, 0x738), (aud[25], aud[26])   # the two carriers: song 25 node 77, song 26 node 80
assert [a for _, a, _, _ in aud[6:]] == [20, 23, 26, 29, 32, 35, 38, 41, 44, 47, 50, 53, 56, 59, 62, 65, 68, 71, 74, 77, 80]
# the earlier maps: UG2 + MW + UG1 (86a9d10f..) = the final map up to 0x195C and in its 96 entries; UG2 + MW (1e98aec5..) in its 69;
# UG2's original (010c929e..) in its 43
m3 = open(p3, 'rb').read(); m2 = open(p2, 'rb').read(); od = open(origp, 'rb').read()
assert len(m3) == 7264 and hashlib.sha256(m3).hexdigest() == '86a9d10f94026aa0a01f955ace1879b9272088f6adb84769c891bdb2ffa968be', 'not the UG2 + MW + UG1 map (86a9d10f..)'
assert len(m2) == 7048 and hashlib.sha256(m2).hexdigest() == '1e98aec576c194b51633381697ae736c344a99757f5a5a36f22463d9887ad37a', 'not the UG2 + MW map (1e98aec5..)'
assert len(od) == 6840 and hashlib.sha256(od).hexdigest() == '010c929e17524d5cfcd54377d14d75de06028a318abf427bb19c122bcd3b0cf5', "not UG2's original map (010c929e..)"
assert d[:0x195C] == m3[:0x195C] and d[0x1960:0x1C60] == m3[0x1960:0x1C60] and struct.unpack_from('<I', m3, 0x195C)[0] == 0x718
assert d[:0x195C] == m2[:0x195C] and d[0x1960:0x1B88] == m2[0x1960:0x1B88] and struct.unpack_from('<I', m2, 0x195C)[0] == 0x6E2
assert d[:0x195C] == od[:0x195C] and d[0x1960:0x1AB8] == od[0x1960:0x1AB8] and struct.unpack_from('<I', od, 0x195C)[0] == 0x6AE
for s in range(27):
    e = tab[3 * s]; a = struct.unpack_from('<H', od, e + 18)[0]; ao = tab[a]; assert struct.unpack_from('<I', od, ao)[0] == aud[s][3] == struct.unpack_from('<I', m2, ao)[0] == struct.unpack_from('<I', m3, ao)[0]
# the first / last entry of each added game, and two ms values
ents = [struct.unpack_from('<II', d, smp + 8 * i) for i in range(nent)]
assert ents[96][0] * 0x80 == 0x1DA94100 and ents[125][0] * 0x80 == 0x2CEB2B00 and ents[96][1] == 167068 and ents[125][1] == 158870 and ents[105][1] == 373704
assert ents[69][0] * 0x80 == 0x15549B80 and ents[95][0] * 0x80 == 0x1D4F1000
L = ['// musicmap.h - generated by tools/archive/make_map_header.py from data/MusicSFx.mpf (SHA-256 %s) + the earlier maps it is compared against' % hashlib.sha256(d).hexdigest()[:8],
     '// (data/MusicSFx_ug2_mw_ug1.mpf, data/MusicSFx_ug2_mw.mpf, data/MusicSFx_ug2_original.mpf). Do not edit.',
     '// The music map image the mod expects in memory: UG2\'s own map with ONE word changed ([0x195C] = the table end / 4) and 83 sample entries',
     '// appended = 126 waves: UG2 1..43, MW 44..69, UG1 70..96, Carbon 97..126.',
     '#define SONG_FILE_LEN %d' % len(d), '#define SONG_OFF_NODETAB 0x%X' % 0x20, '#define SONG_OFF_NODES 0x%X' % nodetab_end,
     '#define SONG_OFF_EVENTS 0x%X' % ev_off, '#define SONG_OFF_EVENTS_END 0x%X' % ev_end, '#define SONG_OFF_WORDS 0x%X' % 0x1950, '#define SONG_OFF_SAMPLES 0x%X' % smp,
     '#define SONG_NUM_NODES %d' % nn, '#define SONG_NUM_EVENTS %d' % nev, '#define SONG_NUM_ENTRIES %d' % nent,
     '#define SONG_WAVE_MW_FIRST 44', '#define SONG_WAVE_MW_LAST 69',
     '#define SONG_WAVE_U1_FIRST 70   // UG1 bank stream s = wave 70 + s (s = 0..26); the songs are streams 1..26 = waves 71..96', '#define SONG_WAVE_U1_LAST 96',
     '#define SONG_WAVE_CB_FIRST 97   // Carbon cb_mus_0 wave w = UG2 wave 95 + w (w = 2..31)', '#define SONG_WAVE_CB_LAST 126',
     'static const unsigned short kAudOff[27] = { %s };   // the audio node of songs 0..26 (file offset = offset in the image); 25 = 0x700, 26 = 0x738 = the carriers' % ', '.join('0x%X' % ao for _, _, ao, _ in aud),
     'static const unsigned short kAudNode[27] = { %s };   // its node number' % ', '.join(str(a) for _, a, _, _ in aud),
     'static const unsigned short kOrigWave[27] = { %s };   // the wave of songs 0..26 in UG2\'s original archive (the image holds them)' % ', '.join(str(w & 0xFFFF) for _, _, _, w in aud),
     'static const unsigned char kMapImage[%d] = {' % len(d)]
for i in range(0, len(d), 32): L.append('  ' + ','.join('0x%02X' % x for x in d[i:i + 32]) + ',')
L.append('};')
open(out, 'w', newline='\n').write('\n'.join(L) + '\n')
print('musicmap.h: image %d B, node table 0x20..0x%X, nodes ..0x%X, events 0x%X..0x%X, words 0x1950, samples 0x%X..0x%X (%d entries: UG2 1..43, MW 44..69, UG1 70..96, Carbon 97..126); aud offs %s; waves %s; carriers node 77 @0x700 word %08X, node 80 @0x738 word %08X'
      % (len(d), nodetab_end, ev_off, ev_off, ev_end, smp, end, nent, ' '.join('0x%X' % ao for _, _, ao, _ in aud), ' '.join(str(w & 0xFFFF) for _, _, _, w in aud), aud[25][3], aud[26][3]))
